    Kode_audio audio;     /**< The kode_audio_*() calls. */
    Kode_wifi wifi;       /**< The kode_wifi_*() calls. */
    Kode_ble ble;         /**< The kode_ble_*() calls. */
    Kode_http http;       /**< The kode_http_*() calls. */
    Kode_net net;         /**< The kode_net_*() calls. */
    Kode_udp udp;         /**< The kode_udp_*() calls. */
    Kode_mqtt mqtt;       /**< The kode_mqtt_*() calls. */
    Kode_battery battery; /**< The kode_battery_*() calls. */
    Kode_power power;     /**< The kode_power_*() calls. */
    Kode_rest rest;       /**< The kode_rest_*() calls. */
    Kode_setting setting; /**< The kode_setting_*() calls. */
    Kode_pin pin;         /**< The kode_pin_*() calls. */
    Kode_i2c i2c;         /**< The kode_i2c_*() calls. */
    Kode_spi spi;         /**< The kode_spi_*() calls. */
    Kode_uart uart;       /**< The kode_uart_*() calls. */
    Kode_ir ir;           /**< The kode_ir_*() calls. */
    Kode_nfc nfc;         /**< The kode_nfc_*() calls. */
    Kode_rfid rfid;       /**< The kode_rfid_*() calls. */
    Kode_display display; /**< The kode_display_*() calls. */
    Kode_touch touch;     /**< The kode_touch_*() calls. */
    Kode_screen screen;   /**< The kode_screen_*() calls. */

    /** @brief kode_init(). */
    void begin(void) const
    {
        kode_init();
    }

