    const char *error(void) const
    {
        return kode_error();
    }

    /** @brief kode_delay(). */
    void delay(uint32_t ms) const
    {
        kode_delay(ms);
    }

    /** @brief kode_exit(). */
    void exit(void) const
    {
        kode_exit();
    }

    /** @brief kode_print(). */
    template <typename... Args>
    void printf(const char *fmt, Args... args) const
    {
        kode_print(fmt, args...);
    }

